style.css:
/* Estilo Gamer */

body {
    background-color: #1a1a2e; /* Color oscuro como fondo */
    color: #e94560; /* Color vibrante para el texto */
    font-family: 'Arial', sans-serif; /* Tipografía moderna */
}

h1, h2, h3 {
    text-shadow: 2px 2px #0f3460; /* Sombra sutil para encabezados */
}

a {
    color: #00adb5; /* Color atractivo para enlaces */
    text-decoration: none;
}

a:hover {
    color: #ffd369; /* Cambio de color al pasar el cursor */
}

/* Botones estilizados */
button {
    background-color: #00adb5;
    border-radius: 10px;
    border: none;
    padding: 10px 20px;
    font-size: 16px;
}

button:hover {
    background-color: #ffd369; /* Efecto hover en botones */
}
